<script>
document.addEventListener('DOMContentLoaded',()=>{if(typeof Chart==='undefined')return;const palette=['#08794d','#f3ad28','#2580db','#825bd6','#26b58b','#e65b75','#82928b'];const summary={{ \Illuminate\Support\Js::from($summary) }};const modes={{ \Illuminate\Support\Js::from($paymentModes) }};const trend={{ \Illuminate\Support\Js::from($trend) }};const ring=(id,labels,values,colors)=>{const empty=!values.some(v=>Number(v)>0);new Chart(document.getElementById(id),{type:'doughnut',data:{labels:empty?['No data']:labels,datasets:[{data:empty?[1]:values,backgroundColor:empty?['#e4ebe7']:colors,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'74%',plugins:{legend:{display:false},tooltip:{enabled:!empty}}}})};ring('fdProgress',['Collected','Outstanding'],[Math.max(0,Number(summary.paid)),Math.max(0,Number(summary.pending))],['#08794d','#bfc9c5']);ring('fdModes',Object.keys(modes),Object.values(modes).map(Number),palette);new Chart(document.getElementById('fdTrend'),{type:'bar',data:{labels:trend.map(r=>r.label),datasets:[{label:'Posted receipts',data:trend.map(r=>r.total),backgroundColor:'#08794d',borderRadius:5,maxBarThickness:40}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'₹'+Number(v).toLocaleString('en-IN')}},x:{grid:{display:false}}}}});});
</script>
